package ru.stepanov.selfcontrol.security; import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*; @Component public class AuthenticationFacade{ public UUID userId(){Authentication a=SecurityContextHolder.getContext().getAuthentication(); if(a==null||!(a.getPrincipal() instanceof TokenService.AuthUser u)) throw new IllegalStateException("Authentication required"); return u.userId();} }
